require('dotenv').config();
const express=require('express'),http=require('http'),cors=require('cors'),path=require('path'),fs=require('fs'),multer=require('multer');
const {Server}=require('socket.io');const {read,write,id,now}=require('./db');const {sign,hash,compare,auth,verify}=require('./auth');const {stkPush}=require('./mpesa');
const app=express(),server=http.createServer(app),io=new Server(server,{cors:{origin:process.env.CORS_ORIGIN||'*',methods:['GET','POST','PATCH','DELETE']}}),PORT=Number(process.env.PORT||3000),HOST=process.env.HOST||'0.0.0.0';
const rateBuckets=new Map();
function rateLimit(key,limit=120,windowMs=60000){const nowMs=Date.now(),b=rateBuckets.get(key)||{start:nowMs,count:0};if(nowMs-b.start>windowMs){b.start=nowMs;b.count=0}b.count++;rateBuckets.set(key,b);return b.count<=limit}
function adminOnly(req,res,next){const email=String(process.env.ADMIN_EMAIL||'').trim().toLowerCase();if(!email||String(req.user?.email||'').toLowerCase()!==email)return res.status(403).json({error:'Administrator access required'});next()}
app.disable('x-powered-by');
app.use((req,res,next)=>{res.setHeader('X-Content-Type-Options','nosniff');res.setHeader('X-Frame-Options','SAMEORIGIN');res.setHeader('Referrer-Policy','strict-origin-when-cross-origin');res.setHeader('Permissions-Policy','camera=(self), microphone=(self)');if(req.path.startsWith('/api/')&&!rateLimit(`${req.ip}:${req.path}`,180,60000))return res.status(429).json({error:'Too many requests. Please try again shortly.'});next()});
const uploadDir=process.env.NEXORA_UPLOAD_DIR ? path.resolve(process.env.NEXORA_UPLOAD_DIR) : path.join(__dirname,'uploads');fs.mkdirSync(uploadDir,{recursive:true});
app.use(cors({origin:process.env.CORS_ORIGIN||'*'}));app.use(express.json({limit:'8mb'}));app.use(express.urlencoded({extended:true}));app.use('/uploads',express.static(uploadDir));app.use(express.static(path.join(__dirname,'..','public'),{etag:false,maxAge:0,setHeaders:(res)=>res.setHeader('Cache-Control','no-store')}));
const allowed=new Set(['image/jpeg','image/png','image/webp','image/gif','video/mp4','video/webm','application/pdf','application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/vnd.ms-excel','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','application/vnd.ms-powerpoint','application/vnd.openxmlformats-officedocument.presentationml.presentation']);
const storage=multer.diskStorage({destination:uploadDir,filename:(req,file,cb)=>{const safe=file.originalname.replace(/[^a-zA-Z0-9._-]/g,'_');cb(null,`${Date.now()}-${Math.random().toString(36).slice(2)}-${safe}`)}});
const upload=multer({storage,limits:{fileSize:100*1024*1024,files:10},fileFilter:(req,file,cb)=>allowed.has(file.mimetype)?cb(null,true):cb(new Error('Unsupported file type'))});
function publicUser(u){if(!u)return null;return{id:u.id,name:u.name,email:u.email,avatar:u.avatar||'',bio:u.bio||'',skills:u.skills||[],education:u.education||'',work:u.work||'',website:u.website||'',premium:!!u.premium,admin:!!(process.env.ADMIN_EMAIL&&String(u.email).toLowerCase()===String(process.env.ADMIN_EMAIL).toLowerCase()),followers:(u.followers||[]).length,following:(u.following||[]).length}}
function getUser(db,uid){return db.users.find(u=>u.id===uid)}
function notify(db,userId,type,text,meta={}){db.notifications=db.notifications||[];db.notifications.unshift({id:id('note'),userId,type,text,meta,read:false,createdAt:now()})}
function cleanUserForList(db,u,me){return {...publicUser(u),following:(getUser(db,me)?.following||[]).includes(u.id)}}
app.get('/api/health',(req,res)=>res.json({ok:true,app:'NEXORA',version:'13.0.0',time:now()}));
app.post('/api/auth/register',async(req,res)=>{try{const{name,email,password}=req.body||{};if(!String(name||'').trim()||!String(email||'').trim()||String(password||'').length<6)return res.status(400).json({error:'Name, email and password (6+ characters) are required'});const db=read(),clean=String(email).trim().toLowerCase();if(db.users.some(u=>u.email===clean))return res.status(409).json({error:'Email already registered'});const user={id:id('usr'),name:String(name).trim().slice(0,80),email:clean,passwordHash:await hash(password),bio:'',avatar:'',premium:false,followers:[],following:[],blocked:[],createdAt:now()};db.users.push(user);write(db);res.json({token:sign(user),user:publicUser(user)})}catch(e){res.status(500).json({error:e.message})}});
app.post('/api/auth/login',async(req,res)=>{try{const db=read(),email=String(req.body?.email||'').trim().toLowerCase(),u=db.users.find(x=>x.email===email);if(!u||!(await compare(String(req.body?.password||''),u.passwordHash)))return res.status(401).json({error:'Invalid email or password'});db.loginEvents=db.loginEvents||[];db.loginEvents.push({id:id('login'),userId:u.id,action:'login',createdAt:now()});db.sessions=db.sessions||[];db.sessions.push({id:id('ses'),userId:u.id,createdAt:now()});write(db);res.json({token:sign(u),user:publicUser(u)})}catch(e){res.status(500).json({error:e.message})}});
app.get('/api/me',auth,(req,res)=>{const u=getUser(read(),req.user.id);if(!u)return res.status(404).json({error:'User not found'});res.json({user:publicUser(u)})});
app.patch('/api/me',auth,(req,res)=>{const db=read(),u=getUser(db,req.user.id);if(!u)return res.status(404).json({error:'User not found'});if(typeof req.body.name==='string'&&req.body.name.trim())u.name=req.body.name.trim().slice(0,80);if(typeof req.body.bio==='string')u.bio=req.body.bio.slice(0,500);if(Array.isArray(req.body.skills))u.skills=req.body.skills.map(x=>String(x).trim()).filter(Boolean).slice(0,20);if(typeof req.body.education==='string')u.education=req.body.education.slice(0,300);if(typeof req.body.work==='string')u.work=req.body.work.slice(0,300);if(typeof req.body.website==='string')u.website=req.body.website.slice(0,300);write(db);res.json({user:publicUser(u)})});
app.post('/api/me/avatar',auth,upload.single('avatar'),(req,res)=>{if(!req.file)return res.status(400).json({error:'Select an image'});const db=read(),u=getUser(db,req.user.id);u.avatar=`/uploads/${req.file.filename}`;write(db);res.json({user:publicUser(u)})});
app.get('/api/users',auth,(req,res)=>{const db=read(),q=String(req.query.q||'').toLowerCase(),me=getUser(db,req.user.id);res.json({users:db.users.filter(u=>u.id!==req.user.id&&!(me.blocked||[]).includes(u.id)&&(!q||u.name.toLowerCase().includes(q)||u.email.includes(q))).slice(0,50).map(u=>cleanUserForList(db,u,req.user.id))})});
app.get('/api/search',auth,(req,res)=>{const db=read(),q=String(req.query.q||'').toLowerCase().trim(),me=getUser(db,req.user.id),blocked=me.blocked||[];res.json({users:db.users.filter(u=>u.id!==req.user.id&&!blocked.includes(u.id)&&(!q||u.name.toLowerCase().includes(q)||u.email.includes(q))).slice(0,20).map(u=>cleanUserForList(db,u,req.user.id)),groups:db.groups.filter(g=>!q||`${g.name} ${g.category||''}`.toLowerCase().includes(q)).slice(0,20),opportunities:db.opportunities.filter(o=>!q||`${o.title} ${o.category} ${o.type}`.toLowerCase().includes(q)).slice(0,20),listings:db.listings.filter(l=>!q||`${l.title} ${l.category}`.toLowerCase().includes(q)).slice(0,20),events:db.events.filter(e=>!q||e.title.toLowerCase().includes(q)).slice(0,20)})});
app.post('/api/users/:id/follow',auth,(req,res)=>{const db=read(),me=getUser(db,req.user.id),t=getUser(db,req.params.id);if(!t||t.id===me.id)return res.status(404).json({error:'User not found'});if((me.blocked||[]).includes(t.id))return res.status(403).json({error:'Unblock this member first'});me.following=me.following||[];t.followers=t.followers||[];const on=me.following.includes(t.id);if(on){me.following=me.following.filter(x=>x!==t.id);t.followers=t.followers.filter(x=>x!==me.id)}else{me.following.push(t.id);t.followers.push(me.id);notify(db,t.id,'follow',`${me.name} started following you`,{userId:me.id})}write(db);res.json({following:!on})});
app.get('/api/posts',auth,(req,res)=>{const db=read(),me=getUser(db,req.user.id),blocked=me.blocked||[];res.json({posts:db.posts.filter(p=>!blocked.includes(p.authorId)).slice().sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).map(p=>({...p,author:publicUser(getUser(db,p.authorId)),likesCount:(p.likes||[]).length,liked:(p.likes||[]).includes(req.user.id),saved:(p.saves||[]).includes(req.user.id),comments:(p.comments||[]).map(c=>({...c,user:publicUser(getUser(db,c.userId))}))}))})});
app.post('/api/posts',auth,upload.array('files',10),(req,res)=>{const db=read(),files=(req.files||[]).map(f=>({name:f.originalname,type:f.mimetype,size:f.size,url:`/uploads/${f.filename}`})),text=String(req.body.text||'').slice(0,5000);if(!text&&!files.length)return res.status(400).json({error:'Write something or attach a file'});const p={id:id('post'),authorId:req.user.id,text,files,likes:[],comments:[],saves:[],shares:0,createdAt:now()};db.posts.push(p);awardXP(db,req.user.id,5,'new post');write(db);io.emit('post:new',p);res.status(201).json({post:p})});
app.patch('/api/posts/:id',auth,(req,res)=>{const db=read(),p=db.posts.find(x=>x.id===req.params.id);if(!p)return res.status(404).json({error:'Post not found'});if(p.authorId!==req.user.id)return res.status(403).json({error:'You can only edit your own post'});p.text=String(req.body.text||'').slice(0,5000);p.updatedAt=now();write(db);res.json({ok:true})});
app.delete('/api/posts/:id',auth,(req,res)=>{const db=read(),i=db.posts.findIndex(x=>x.id===req.params.id);if(i<0)return res.status(404).json({error:'Post not found'});if(db.posts[i].authorId!==req.user.id)return res.status(403).json({error:'You can only delete your own post'});db.posts.splice(i,1);write(db);res.json({ok:true})});
app.post('/api/posts/:id/like',auth,(req,res)=>{const db=read(),p=db.posts.find(x=>x.id===req.params.id);if(!p)return res.status(404).json({error:'Post not found'});p.likes=p.likes||[];const liked=p.likes.includes(req.user.id);p.likes=liked?p.likes.filter(x=>x!==req.user.id):p.likes.concat(req.user.id);if(!liked&&p.authorId!==req.user.id)notify(db,p.authorId,'like',`${getUser(db,req.user.id).name} liked your post`,{postId:p.id});write(db);res.json({liked:!liked,likesCount:p.likes.length})});
app.post('/api/posts/:id/comment',auth,(req,res)=>{const db=read(),p=db.posts.find(x=>x.id===req.params.id),text=String(req.body.text||'').trim();if(!p||!text)return res.status(400).json({error:'Post and comment are required'});const c={id:id('com'),userId:req.user.id,text:text.slice(0,1000),createdAt:now()};p.comments=p.comments||[];p.comments.push(c);if(p.authorId!==req.user.id)notify(db,p.authorId,'comment',`${getUser(db,req.user.id).name} commented on your post`,{postId:p.id});write(db);res.status(201).json({comment:{...c,user:publicUser(getUser(db,req.user.id))}})});
app.post('/api/posts/:id/share',auth,(req,res)=>{const db=read(),p=db.posts.find(x=>x.id===req.params.id);if(!p)return res.status(404).json({error:'Post not found'});p.shares=(p.shares||0)+1;write(db);res.json({shares:p.shares})});
app.post('/api/posts/:id/save',auth,(req,res)=>{const db=read(),p=db.posts.find(x=>x.id===req.params.id);if(!p)return res.status(404).json({error:'Post not found'});p.saves=p.saves||[];const saved=p.saves.includes(req.user.id);p.saves=saved?p.saves.filter(x=>x!==req.user.id):p.saves.concat(req.user.id);write(db);res.json({saved:!saved})});
