app.post('/api/messages/:userId',auth,(req,res)=>{const text=String(req.body.text||'').trim(),db=read(),to=getUser(db,req.params.userId),me=getUser(db,req.user.id);if(!to||!text)return res.status(400).json({error:'Recipient and message are required'});if((me.blocked||[]).includes(to.id)||(to.blocked||[]).includes(me.id))return res.status(403).json({error:'Messaging is unavailable between these members'});db.directMessages=db.directMessages||[];const m={id:id('dm'),fromId:req.user.id,toId:to.id,text:text.slice(0,2000),createdAt:now()};db.directMessages.push(m);notify(db,to.id,'message',`${me.name} sent you a message`,{userId:me.id});write(db);const out={...m,user:publicUser(me)};const sid=online.get(to.id);if(sid)io.to(sid).emit('direct:message',out);res.status(201).json({message:out})});
app.post('/api/notifications/read',auth,(req,res)=>{const db=read();(db.notifications||[]).filter(n=>n.userId===req.user.id).forEach(n=>n.read=true);write(db);res.json({ok:true})});
