app.post('/api/events/:id/rsvp',auth,(req,res)=>{const db=read(),e=db.events.find(x=>x.id===req.params.id);if(!e)return res.status(404).json({error:'Event not found'});e.attendees=e.attendees||[];const yes=e.attendees.includes(req.user.id);if(yes)e.attendees=e.attendees.filter(x=>x!==req.user.id);else{if(e.capacity&&e.attendees.length>=e.capacity)return res.status(409).json({error:'Event is full'});e.attendees.push(req.user.id)}write(db);res.json({going:!yes,count:e.attendees.length})});
