app.post('/api/payments/mpesa/stk',auth,async(req,res)=>{let phone=String(req.body.phone||'').replace(/\s+/g,'');if(/^0[17]\d{8}$/.test(phone))phone='254'+phone.slice(1);const amount=Number(req.body.amount||100);if(!/^254[17]\d{8}$/.test(phone))return res.status(400).json({error:'Use 07XXXXXXXX, 01XXXXXXXX or 2547XXXXXXXX format'});if(amount!==100)return res.status(400).json({error:'NEXORA Premium costs KSh 100/month'});try{const response=await stkPush(phone,amount,`NEXORA-${req.user.id}`);const db=read();db.payments=db.payments||[];db.payments.push({id:id('pay'),userId:req.user.id,phone,amount,checkoutRequestId:response.CheckoutRequestID||null,merchantRequestId:response.MerchantRequestID||null,response,status:'pending',createdAt:now()});write(db);res.json({ok:true,response})}catch(e){res.status(503).json({error:e.message})}});
app.post('/api/payments/mpesa/callback',(req,res)=>{const cb=req.body?.Body?.stkCallback,db=read();if(!cb)return res.json({ResultCode:0,ResultDesc:'Accepted'});const p=(db.payments||[]).slice().reverse().find(x=>x.checkoutRequestId===cb.CheckoutRequestID);if(p){p.status=cb.ResultCode===0?'paid':'failed';p.callback=cb;if(cb.ResultCode===0){const u=getUser(db,p.userId);if(u){u.premium=true;u.premiumAt=now()}}}write(db);res.json({ResultCode:0,ResultDesc:'Accepted'})});
