const online=new Map();
io.use((socket,next)=>{try{socket.user=verify(socket.handshake.auth?.token);next()}catch{next(new Error('Unauthorized'))}});
io.on('connection',socket=>{online.set(socket.user.id,socket.id);socket.emit('presence:list',[...online.keys()]);socket.broadcast.emit('presence:update',{userId:socket.user.id,online:true});socket.on('group:join',gid=>socket.join(`group:${gid}`));socket.on('group:message',({groupId,text})=>{const db=read(),g=db.groups.find(x=>x.id===groupId),t=String(text||'').trim();if(!g||!(g.members||[]).includes(socket.user.id)||!t)return;db.messages=db.messages||[];const m={id:id('msg'),groupId,userId:socket.user.id,text:t.slice(0,2000),createdAt:now()};db.messages.push(m);write(db);io.to(`group:${groupId}`).emit('group:message',{...m,user:publicUser(getUser(db,socket.user.id))})});socket.on('typing',({to,typing})=>{const sid=online.get(to);if(sid)io.to(sid).emit('typing',{from:socket.user.id,typing:!!typing})});socket.on('call:offer',({to,offer})=>online.get(to)&&io.to(online.get(to)).emit('call:offer',{from:socket.user.id,fromName:socket.user.name,offer}));socket.on('call:answer',({to,answer})=>online.get(to)&&io.to(online.get(to)).emit('call:answer',{from:socket.user.id,answer}));socket.on('call:ice',({to,candidate})=>online.get(to)&&io.to(online.get(to)).emit('call:ice',{from:socket.user.id,candidate}));socket.on('call:end',({to})=>online.get(to)&&io.to(online.get(to)).emit('call:end',{from:socket.user.id}));socket.on('disconnect',()=>{if(online.get(socket.user.id)===socket.id)online.delete(socket.user.id);socket.broadcast.emit('presence:update',{userId:socket.user.id,online:false})})});

