app.post('/api/listings/:id/order',auth,(req,res)=>{const db=read(),l=db.listings.find(x=>x.id===req.params.id);if(!l)return res.status(404).json({error:'Listing not found'});if(l.sellerId===req.user.id)return res.status(400).json({error:'You cannot order your own listing'});const qty=Math.max(1,Math.min(99,Number(req.body.qty||1)));const total=Number(l.price||0)*qty;const o={id:id('ord'),listingId:l.id,buyerId:req.user.id,sellerId:l.sellerId,qty,total,currency:'KES',status:'pending',createdAt:now()};db.orders.push(o);notify(db,l.sellerId,'order',`${getUser(db,req.user.id).name} placed an order for ${l.title}`,{orderId:o.id});write(db);res.status(201).json({order:o})});
app.patch('/api/orders/:id/status',auth,(req,res)=>{const db=read(),o=db.orders.find(x=>x.id===req.params.id);if(!o)return res.status(404).json({error:'Order not found'});if(o.sellerId!==req.user.id&&o.buyerId!==req.user.id)return res.status(403).json({error:'Not allowed'});const allowed=['pending','confirmed','processing','shipped','delivered','cancelled'];const st=String(req.body.status||'pending');if(!allowed.includes(st))return res.status(400).json({error:'Invalid order status'});if(o.status==='delivered'&&st!=='delivered')return res.status(400).json({error:'Delivered orders cannot be changed'});o.status=st;o.updatedAt=now();write(db);res.json({order:o})});
app.post('/api/listings/:id/reviews',auth,(req,res)=>{const db=read(),l=db.listings.find(x=>x.id===req.params.id);if(!l)return res.status(404).json({error:'Listing not found'});const rating=Math.max(1,Math.min(5,Number(req.body.rating||5))),text=String(req.body.text||'').trim().slice(0,1000);if(!text)return res.status(400).json({error:'Review text is required'});if(db.reviews.some(r=>r.listingId===l.id&&r.userId===req.user.id))return res.status(409).json({error:'You already reviewed this listing'});const r={id:id('rev'),listingId:l.id,userId:req.user.id,rating,text,createdAt:now()};db.reviews.push(r);write(db);res.status(201).json({review:{...r,user:publicUser(getUser(db,req.user.id))}})});
