app.post('/api/posts/:id/reaction',auth,(req,res)=>{const db=read(),p=db.posts.find(x=>x.id===req.params.id);if(!p)return res.status(404).json({error:'Post not found'});const types=['like','love','laugh','wow','sad','angry'],type=String(req.body.type||'like');if(!types.includes(type))return res.status(400).json({error:'Invalid reaction'});db.postReactions=db.postReactions||[];const old=db.postReactions.find(r=>r.postId===p.id&&r.userId===req.user.id);if(old){if(old.type===type)db.postReactions=db.postReactions.filter(r=>r!==old);else old.type=type}else db.postReactions.push({id:id('react'),postId:p.id,userId:req.user.id,type,createdAt:now()});write(db);res.json({reactions:db.postReactions.filter(r=>r.postId===p.id).reduce((a,r)=>(a[r.type]=(a[r.type]||0)+1,a),{})})});
