function timeOfDayGreeting(){const h=new Date().getHours();if(h<5)return'burning the midnight oil';if(h<12)return'Good morning';if(h<17)return'Good afternoon';if(h<21)return'Good evening';return'Good night'}
function xpLevel(xp){return Math.floor((xp||0)/100)+1}
function awardXP(db,userId,amount,reason){const u=getUser(db,userId);if(!u)return;u.xp=(u.xp||0)+amount;const newLevel=xpLevel(u.xp);if(newLevel>(u.level||1)){notify(db,userId,'levelup',`🎉 You reached Level ${newLevel} on NEXORA!`,{level:newLevel})}u.level=newLevel;return{xp:u.xp,level:u.level,gained:amount,reason}}
function buildAIReply(db,user,rawMessage){
  const q=String(rawMessage||'').trim();
  const x=q.toLowerCase();
  const suggestions=[];
  let answer=null;
  const greetRe=/^(hi|hello|hey|yo|sup|good (morning|afternoon|evening)|howdy)\b/;
  const thanksRe=/\b(thanks|thank you|thx|appreciate)\b/;
  const helpRe=/^(what can you do|help|help me|capabilities|features|who are you)\??$/;
  if(greetRe.test(x)){
    const streak=user.streak||0;
    answer=`${timeOfDayGreeting()}, ${user.name.split(' ')[0]}! 👋 ${streak>0?`You're on a ${streak}-day streak — keep it going! `:''}What are you in the mood for today — jobs, the marketplace, learning, or just catching up on your feed?`;
    suggestions.push('Find work for me','Show trending posts','Check my streak');
  }else if(thanksRe.test(x)){
    answer=`Anytime, ${user.name.split(' ')[0]}! I'm always here if you need to navigate NEXORA, get unstuck, or just want ideas. 🙌`;
  }else if(helpRe.test(x)){
    answer='I\'m your NEXORA guide. I can help you find jobs and gigs, buy or sell in the marketplace, plan your learning, catch up on messages, manage premium/payments, stay safe, and track your streak, XP and leaderboard rank. Just ask naturally — like "find me remote work" or "what\'s trending?".';
    suggestions.push('Find work for me','How do I sell something?','Show leaderboard');
  }else if(/streak|check.?in|\bxp|\blevel|\bpoints|\bbadge/.test(x)){
    const streak=user.streak||0,xp=user.xp||0,level=xpLevel(xp);
    const today=now().slice(0,10);
    const checkedInToday=db.checkins.some(c=>c.userId===user.id&&c.date===today);
    answer=`🔥 Streak: ${streak} day${streak===1?'':'s'}\n⭐ Level ${level} (${xp} XP)\n${checkedInToday?'You already checked in today — nice!':'You haven\'t checked in today yet — do that to keep your streak alive.'}`;
    suggestions.push(checkedInToday?'Show leaderboard':'Daily check-in');
  }else if(/leaderboard|\brank|top user|who.?s winning/.test(x)){
    const top=db.users.slice().sort((a,b)=>(b.xp||0)-(a.xp||0)).slice(0,3).map((u,i)=>`${i+1}. ${u.name} — ${u.xp||0} XP`).join('\n');
    answer=top?`🏆 Top NEXORA members right now:\n${top}\n\nOpen the Leaderboard to see the full ranking and your own position.`:'🏆 The leaderboard is quiet right now — be one of the first to earn XP by checking in daily and staying active!';
    suggestions.push('Open Leaderboard');
  }else if(/communit(y|ies)|\bgroup/.test(x)){
    answer=`👥 There are ${db.groups.length} communities on NEXORA. Join one that matches your interests, or start your own around a topic you care about.`;
    suggestions.push('Open Communities');
  }else if(/\bevent|\brsvp\b|meetup/.test(x)){
    const upcoming=db.events.filter(e=>!e.date||new Date(e.date)>=new Date()).length;
    answer=`📅 There ${upcoming===1?'is':'are'} ${upcoming} upcoming event${upcoming===1?'':'s'}. Open Events to RSVP, or host your own in a couple of taps.`;
    suggestions.push('Open Events');
  }else if(/\bpremium\b|\bpayment|mpesa|subscri/.test(x)){
    answer=user.premium?'💎 You\'re already a NEXORA Premium member — thank you for supporting the platform! Check Wallet for your payment history.':'NEXORA Premium is KSh 100/month via M-Pesa STK Push. Open Premium/Wallet, enter your phone number, and approve the prompt on your phone. Production use needs real Safaricom Daraja credentials configured by the site owner.';
    suggestions.push('Open Wallet');
  }else if(/\bsafe\b|\breport|\bblock|security|password|2fa/.test(x)){
    answer='🛡️ Your safety matters. Use Safety to report content or block someone — it\'s private and reviewed by admins. In Settings → Security you can change your password, enable a 2FA preference, and sign other sessions out.';
    suggestions.push('Open Safety','Open Settings');
  }else if(/\bmessag|\bchat\b|\bcall\b|\bdm\b|conversation/.test(x)){
    const unread=db.directMessages.filter(m=>m.toId===user.id&&!m.read).length;
    answer=unread?`✉️ You have ${unread} unread message${unread===1?'':'s'} waiting. Open Messages to catch up.`:'Your inbox is all caught up! Open Messages to start a new conversation — text, and where supported, voice/video calling too.';
    suggestions.push('Open Messages');
  }else if(/\bprofile|\bbio\b|\bavatar|edit my/.test(x)){
    answer='👤 Open Profile to update your photo, bio, skills, education and work history. A complete profile gets more followers and better opportunity matches.';
    suggestions.push('Open Profile');
  }else if(/\btrend|\bpopular|\bexplore|what.?s (new|happening)/.test(x)){
    const trending=db.posts.slice().sort((a,b)=>((b.likes||[]).length+(b.comments||[]).length)-((a.likes||[]).length+(a.comments||[]).length)).slice(0,3);
    answer=trending.length?`📈 Trending on NEXORA right now:\n${trending.map(p=>`• "${(p.text||'[media]').slice(0,60)}" — ${(p.likes||[]).length} likes`).join('\n')}\n\nOpen Explore to see more.`:'Nothing trending yet — be the first to post something great!';
    suggestions.push('Open Explore');
  }else if(/stud(y|ies)|\bcourse|education|\blearn|\bskill/.test(x)){
    const progressEntries=Object.entries(db.courseProgress||{}).filter(([k])=>k.startsWith(`${user.id}:`));
    const started=progressEntries.length;
    const avg=started?Math.round(progressEntries.reduce((n,[,v])=>n+Number(v||0),0)/started):0;
    answer=started?`🎓 You've started ${started} course${started===1?'':'s'} with ${avg}% average progress. Keep chipping away — every lesson gives you momentum.`:'Open Education to start a course — Digital Skills, Entrepreneurship, Career & CV Mastery, or Personal Finance. Small daily progress beats cramming.';
    suggestions.push('Open Education');
  }else if(/\bmarket|\bsell|\bbuy\b|\bproduct|\bshop|\blisting/.test(x)){
    const listings=db.listings.slice().sort((a,b)=>b.createdAt.localeCompare(a.createdAt));
    const top=listings.slice(0,3).map(l=>`• ${l.title} — KSh ${l.price}`).join('\n');
    answer=`🛒 The Marketplace has ${listings.length} active listing${listings.length===1?'':'s'}.${top?`\n\nJust added:\n${top}`:''}\n\nTo sell: open Marketplace → New Listing, add photos and a price. To buy: open a listing and place an order or message the seller.`;
    suggestions.push('Open Marketplace','Create a listing');
  }else if(/\bjob|\bwork\b|\bcareer|\bintern|\bhire|\bfreelance|\bgig/.test(x)){
    const open=db.opportunities.slice().sort((a,b)=>b.createdAt.localeCompare(a.createdAt));
    const top=open.slice(0,3).map(o=>`• ${o.title}${o.remote?' (remote)':''}`).join('\n');
    answer=`💼 There ${open.length===1?'is':'are'} currently ${open.length} opportunit${open.length===1?'y':'ies'} posted.${top?`\n\nMost recent:\n${top}`:''}\n\nOpen Opportunities, filter by Jobs, Freelance or Internships, and tap Apply on anything that fits.`;
    suggestions.push('Open Opportunities','Post an opportunity');
  }else{
    answer='✦ I can help with jobs, the marketplace, education, messages, premium/payments, safety, communities, events, your profile, or your streak/XP and the leaderboard. What would you like to do?';
    suggestions.push('Find work for me','Show trending posts','Check my streak');
  }
  return{answer,suggestions};
}
async function externalAI(db,user,q,mode){
  const key=String(process.env.NEXORA_AI_API_KEY||'').trim();
  if(!key)return null;
  const base=String(process.env.NEXORA_AI_BASE_URL||'https://api.openai.com/v1').replace(/\/$/,'');
  const model=String(process.env.NEXORA_AI_MODEL||'').trim();
  if(!model)return null;
  const history=(db.aiChats||[]).filter(x=>x.userId===user.id).slice(-12).flatMap(x=>[
    {role:'user',content:String(x.message||'').replace(/^\[Mode: [^\]]+\] /,'')},
    {role:'assistant',content:String(x.answer||'')}
  ]);
  const system=`You are NEXORA, a warm, capable AI companion inside a social app. Talk naturally like a modern general-purpose assistant. You can help with everyday conversation, decisions, planning, writing, jobs, marketplace, communities, messaging, learning and life. Do not pretend to have performed actions you cannot perform. If a request requires live app data, explain what you can access. Be concise but useful. Current NEXORA mode: ${mode||'Companion'}. User name: ${user.name||'there'}.`;
  const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),30000);
  try{
    const r=await fetch(base+'/chat/completions',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+key},body:JSON.stringify({model,messages:[{role:'system',content:system},...history,{role:'user',content:q}],temperature:0.7,max_tokens:900}),signal:controller.signal});
    const data=await r.json().catch(()=>({}));
    if(!r.ok)throw new Error(data?.error?.message||`AI provider returned ${r.status}`);
    const answer=String(data?.choices?.[0]?.message?.content||'').trim();
    if(!answer)throw new Error('AI provider returned an empty response');
    return answer;
  }finally{clearTimeout(timer)}
}
app.post('/api/ai',auth,async(req,res)=>{const db=read(),q=String(req.body.message||'').trim().slice(0,4000),mode=String(req.body.mode||'Companion').slice(0,30);if(!q)return res.status(400).json({error:'Message required'});const user=getUser(db,req.user.id);try{let answer=await externalAI(db,user,q,mode);if(!answer){const fallback=buildAIReply(db,user,q);answer=fallback.answer;var suggestions=fallback.suggestions}else suggestions=[];db.aiChats=db.aiChats||[];db.aiChats.push({id:id('ai'),userId:req.user.id,message:q,answer,mode,createdAt:now()});db.aiChats=db.aiChats.slice(-1000);write(db);res.json({answer,suggestions,provider:process.env.NEXORA_AI_API_KEY?'live':'local'})}catch(e){console.error('AI error:',e.message);res.status(502).json({error:'NEXORA AI could not reach the configured AI service. Check the AI settings and try again.'})}});
